/**
 * Agent Registry catalog.
 *
 * Agent definitions are NOT handwritten duplicates: they are generated from a
 * combinatorial matrix of real domain blueprints (80 professional domains) and
 * genuinely different specialization profiles (50 specialist archetypes).
 * Each combination yields a unique id, specialization, system instructions,
 * capabilities, inputs/outputs, model requirements, tools, workflow, verification,
 * security profile, cost metadata, fallback, version, health and eval config.
 *
 * This keeps 4,000+ agents genuinely differentiated without 4,000 duplicated
 * source files, while preserving extensibility for custom agents.
 */

export interface AgentDefinition {
  key: string;
  slug: string;
  name: string;
  categorySlug: string;
  specialization: string;
  systemInstructions: string;
  capabilities: string[];
  inputs: string[];
  outputs: string[];
  modelRequirements: string[];
  toolPermissions: string[];
  apiRequirements: string[];
  workflow: string[];
  verificationRules: string[];
  securityPermissions: string[];
  costUsage: { estimatedTokens: number; estimatedCents: number; priority: 'low' | 'medium' | 'high' };
  fallbackStrategy: string;
  evaluationConfig: { metrics: string[]; rubric: string; testCases: string[] };
}

interface DomainBlueprint {
  slug: string;
  name: string;
  description: string;
  domainBusiness: string;
  domainKnowledge: string;
  domainTools: string[];
  domainModelCapabilities: string[];
  domainSecurity: string[];
  domainVerification: string[];
  domainOutput: string[];
  domainCostBase: number;
}

interface SpecializationProfile {
  key: string;
  name: string;
  responsibility: string;
  inputs: string[];
  outputs: string[];
  workflow: string[];
  verification: string[];
  security: string[];
  modelCapabilities: string[];
}

