export const AGENT_CATEGORIES = DOMAINS.map((domain) => ({
  slug: domain.slug,
  name: domain.name,
  description: domain.description,
  icon: 'bot',
}));

function buildDefinition(domain: DomainBlueprint, spec: SpecializationProfile, index: number): AgentDefinition {
  const key = `${domain.slug}-${spec.key}`;
  const slug = `${domain.slug}-${spec.key}-${String(index + 1).padStart(3, '0')}`;
  const name = `${domain.name} ${spec.name}`;
  const capabilities = [...new Set([...spec.modelCapabilities, ...domain.domainModelCapabilities])];

  const systemInstructions = [
    `You are the ${name} within AKBARAL!, a specialist agent for the ${domain.name} domain.`,
    `Domain business: ${domain.domainBusiness}.`,
    `Domain knowledge: ${domain.domainKnowledge}.`,
    `Your role: ${spec.responsibility}.`,
    'You only use verified inputs; you never fabricate sources, credentials, metrics, or availability.',
    `Constraints: ${[...new Set([...domain.domainSecurity, ...spec.security])].join('; ')}.`,
    `Your verification rules: ${spec.verification.join('; ')}.`,
  ].join('\n');

  return {
    key,
    slug,
    name,
    categorySlug: domain.slug,
    specialization: `${domain.name} / ${spec.name}`,
    systemInstructions,
    capabilities,
    inputs: spec.inputs,
    outputs: spec.outputs,
    modelRequirements: capabilities.includes('reasoning') ? ['reasoning'] : ['writing'],
    toolPermissions: domain.domainTools,
    apiRequirements: domain.domainTools.includes('web_search') ? ['AKBARAL_WEB_SEARCH_ENDPOINT (optional proxy)'] : [],
    workflow: spec.workflow.map((step) => `${step} (${domain.slug})`),
    verificationRules: spec.verification,
    securityPermissions: [...new Set([...domain.domainSecurity, ...spec.security])],
    costUsage: {
      estimatedTokens: 2000 + domain.domainCostBase * 500,
      estimatedCents: domain.domainCostBase,
      priority: domain.domainCostBase >= 3 ? 'high' : domain.domainCostBase === 2 ? 'medium' : 'low',
    },
    fallbackStrategy: `If primary model/provider unavailable, reroute to default balanced model; if source/tool unavailable, return a structured gap report.`,
    evaluationConfig: {
      metrics: ['factual accuracy', 'specialization coverage', 'verification compliance', 'output completeness'],
      rubric: `Score output against ${domain.name} best practices and ${spec.responsibility}.`,
      testCases: [`${domain.name} task for "${spec.responsibility}"`, `edge case for ${domain.slug} target`, `missing-input test`],
    },
  };
}

/**
 * Generate the full agent catalog (domains x specialization profiles).
 */
export function generateAgentDefinitions(): AgentDefinition[] {
  const definitions: AgentDefinition[] = [];
  for (const domain of DOMAINS) {
    SPECIALIZATIONS.forEach((spec, index) => {
      definitions.push(buildDefinition(domain, spec, index));
    });
  }
  return definitions;
}

export function agentDefinitionCount(): number {
  return DOMAINS.length * SPECIALIZATIONS.length;
}

export function listDomainCount(): number {
  return DOMAINS.length;
}
